{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — About</title>
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--accent:#2b6cb0;--muted:#65748b;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0f1724;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;background:linear-gradient(135deg,rgba(43,108,176,0.12),rgba(43,108,176,0.06));border-radius:10px;display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:980px;margin:36px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .panel{background:var(--card);border-radius:12px;padding:26px;box-shadow:0 6px 20px rgba(17,24,39,0.06)}
    h1{margin:0 0 6px;font-size:26px;color:#09203a}
    p.lead{margin:0;color:var(--muted);line-height:1.45}
    .aside{position:relative;overflow:hidden;border-radius:12px}
    /* inline svg pattern as decorative background */
    .svg-bg{position:absolute;inset:0;opacity:0.14}
    .meta{display:flex;flex-direction:column;gap:12px;margin-top:18px}
    .pill{background:linear-gradient(90deg,rgba(43,108,176,0.06),rgba(43,108,176,0.03));padding:10px;border-radius:10px;font-weight:600;color:var(--accent);width:max-content}
    section{margin-top:28px}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
    .card{background:linear-gradient(180deg,var(--card),var(--glass));padding:18px;border-radius:10px}
    footer{margin:40px auto 80px;text-align:center;color:var(--muted)}
    /* reveal animations */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s cubic-bezier(.2,.9,.3,1),transform .6s cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    /* small screens */
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.aside{order:-1}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Wellness design for busy lives</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I Am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Praise</a>
      <a href="book.html">Plan</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="hero">
      <div class="panel reveal">
        <h1>How I help leaders keep steady, without friction</h1>
        <p class="lead">I design simple habits and practical frameworks so you keep focus and feel anchored across busy weeks. My work centers on making dependable moves — no sweeping programs, just protocols that stick.</p>
        <div class="meta">
          <div class="pill">VIP Day & Private Rhythm Coaching</div>
          <div style="color:var(--muted)">Sessions emphasize habit architecture, measurable outcomes, and repeatable practices you can own.</div>
        </div>
      </div>

      <aside class="aside panel reveal">
        <svg class="svg-bg" viewBox="0 0 600 400" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <defs>
            <pattern id="pAbout" width="40" height="40" patternUnits="userSpaceOnUse" patternTransform="rotate(18)">
              <rect width="40" height="40" fill="#f8fafc" />
              <circle cx="10" cy="10" r="2" fill="#e6f0ff" />
              <circle cx="30" cy="30" r="2" fill="#eaf4ff" />
            </pattern>
            <linearGradient id="gAbout" x1="0" x2="1">
              <stop offset="0" stop-color="#eaf2ff" />
              <stop offset="1" stop-color="#ffffff" />
            </linearGradient>
          </defs>
          <rect width="100%" height="100%" fill="url(#pAbout)" />
          <rect x="0" y="0" width="100%" height="100%" fill="url(#gAbout)" opacity="0.7"/>
        </svg>
        <div style="position:relative;padding:14px">
          <strong style="display:block">A different kind of support</strong>
          <p style="margin-top:8px;color:var(--muted);line-height:1.45">Clients work with me to build clear levered routines: choices that produce results with far less mental overhead. Expect a compact set of practices, mapped to your calendar and language.</p>
          <div style="margin-top:14px;display:flex;gap:10px">
            <a href="book.html" style="text-decoration:none;padding:10px 14px;border-radius:8px;background:var(--accent);color:#fff;font-weight:700">{{PRIMARY_CTA_LABEL}}</a>
            <a href="contact.html" style="text-decoration:none;padding:10px 14px;border-radius:8px;border:1px solid rgba(9,32,58,0.06);color:var(--muted);font-weight:700">Connect</a>
          </div>
        </div>
      </aside>
    </div>

    <section class="reveal">
      <h2 style="margin-top:0">Approach & Outcomes</h2>
      <div class="grid">
        <div class="card">
          <strong>Outcome-focused habits</strong>
          <p style="margin:8px 0 0;color:var(--muted)">We choose 2–3 behaviors to shift measurable signals like sleep consistency, mid-day energy, and weekly movement frequency.</p>
        </div>
        <div class="card">
          <strong>Built frameworks</strong>
          <p style="margin:8px 0 0;color:var(--muted)">Short protocols that sit in your day — morning scaffolds, midday resets, and evening wind-downs — designed to be repeatable.</p>
        </div>
        <div class="card">
          <strong>Accountable design</strong>
          <p style="margin:8px 0 0;color:var(--muted)">Tools to track progress without friction: a single metric and a simple check-in the team can use.</p>
        </div>
      </div>
    </section>

    <section class="reveal">
      <h2>Why it works</h2>
      <p style="color:var(--muted)">Instead of introducing many new habits at once, we scaffold one robust routine and tie it to existing cues. That small, strategic change compounds across weeks and holds under pressure.</p>
    </section>

    <section class="reveal">
      <h2>Get started</h2>
      <p style="color:var(--muted)">Book a short strategy call or schedule a VIP Day to map a focused plan. Reach out at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
      <div style="margin-top:12px">
        <a href="book.html" style="padding:12px 18px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:800">Plan a session</a>
      </div>
    </section>

  </main>

  <footer>
    <div style="max-width:980px;margin:0 auto;padding:12px;color:var(--muted)">Serving leaders in {{CITY}}, {{STATE}} — <span style="font-weight:700">{{BUSINESS_NAME}}</span></div>
  </footer>

  <script>
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches){
        document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible')});
        return;
      }
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if (e.isIntersecting) e.target.classList.add('visible'); });
      },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(function(el){obs.observe(el)});
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Offerings</title>
  <style>
    :root{--bg:#ffffff;--card:#ffffff;--accent:#0f6fbf;--muted:#6b7280}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:linear-gradient(180deg,#fbfdff 0%, #ffffff 100%);color:#071029}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 24px}
    .brand{display:flex;align-items:center;gap:12px}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    .container{max-width:980px;margin:26px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .panel{background:var(--card);border-radius:12px;padding:20px;box-shadow:0 8px 30px rgba(9,34,61,0.04)}
    h1{margin:0 0 6px}
    .muted{color:var(--muted)}
    ul.service-list{list-style:none;padding:0;margin:12px 0 0;display:flex;flex-direction:column;gap:12px}
    li.service{padding:12px;border-radius:10px;border:1px solid rgba(11,54,96,0.04);display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:800;color:var(--accent)}
    /* Session Planner styles */
    .planner{margin-top:18px;border-radius:10px;padding:14px;background:linear-gradient(180deg,#fff,#fbfdff);border:1px solid rgba(11,54,96,0.03)}
    .planner label{display:block;font-size:13px;color:var(--muted);margin-top:10px}
    .planner input[type="text"],.planner textarea, .planner select{width:100%;padding:10px;border-radius:8px;border:1px solid #e6eef8;margin-top:6px}
    .planner .row{display:flex;gap:10px}
    .btn{background:var(--accent);color:#fff;padding:10px 12px;border-radius:10px;border:none;font-weight:800;cursor:pointer}
    .btn.secondary{background:transparent;color:var(--accent);border:1px solid rgba(15,111,191,0.12)}
    .output{background:#f8fbff;border-radius:8px;padding:10px;margin-top:10px;white-space:pre-wrap;font-family:monospace;color:#09203a}
    /* reveal */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s cubic-bezier(.2,.9,.3,1),transform .6s cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#eaf4ff,#ffffff);display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--accent)">W</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Practical support for focused people</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I Am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Praise</a>
      <a href="book.html">Plan</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <div class="panel reveal">
        <h1>Offerings: concise, actionable support</h1>
        <p class="muted">Choose a model that fits your rhythm. All work emphasizes measurable habits, simple frameworks, and practical outcomes.</p>

        <ul class="service-list">
          <li class="service">
            <div>
              <div style="font-weight:800">Focused Reset — VIP Day</div>
              <div style="font-size:13px;color:var(--muted)">A intensive single day to design a bespoke daily map and an accountability toolkit.</div>
            </div>
            <div class="price">Investment: One day</div>
          </li>

          <li class="service">
            <div>
              <div style="font-weight:800">Steady Month — Support Package</div>
              <div style="font-size:13px;color:var(--muted)">Four checkpoints and a living plan you can follow. Good for embedding a new routine.</div>
            </div>
            <div class="price">Investment: 4 sessions</div>
          </li>

          <li class="service">
            <div>
              <div style="font-weight:800">Pulse Check — Short consult</div>
              <div style="font-size:13px;color:var(--muted)">30–45 minute clarity calls to correct course and tighten the plan.</div>
            </div>
            <div class="price">Investment: Single session</div>
          </li>
        </ul>

        <section class="planner" aria-labelledby="plannerTitle">
          <h3 id="plannerTitle">Session Planner</h3>
          <p class="muted">Build a short plan you can use in a single VIP Day or a month-long engagement. Export the plan as plain text to share or save.</p>

          <label for="goal">Primary outcome (one sentence)</label>
          <input id="goal" type="text" placeholder="e.g. consistent early wake with steady energy" />

          <label for="focus">Main areas to address</label>
          <select id="focus" multiple size="4">
            <option value="sleep">Sleep consistency</option>
            <option value="movement">Movement & strength</option>
            <option value="stress">Stress resets</option>
            <option value="nutrition">Simple nutrition anchors</option>
            <option value="rhythm">Daily rhythm & transitions</option>
          </select>

          <div class="row">
            <label style="flex:1">Weekly time to invest (hours)
              <input id="hours" type="text" placeholder="e.g. 2" />
            </label>
            <label style="flex:1">Pace
              <select id="pace"><option>Low</option><option selected>Moderate</option><option>High</option></select>
            </label>
          </div>

          <label for="notes">Personal constraints or notes</label>
          <textarea id="notes" rows="3" placeholder="Work schedule, travel, medical notes (non-medical), preferences"></textarea>

          <div style="margin-top:10px;display:flex;gap:8px">
            <button id="buildPlan" class="btn">Build plan</button>
            <button id="clearPlan" class="btn secondary" type="button">Clear</button>
          </div>

          <div id="result" class="output" aria-live="polite"></div>
          <div style="margin-top:8px;display:flex;gap:8px">
            <button id="copyBtn" class="btn" style="background:#0a4f8a">Copy text</button>
            <a id="bookNow" class="btn secondary" href="{{PRIMARY_CTA_URL}}">Schedule a VIP Day</a>
          </div>
        </section>

      </div>

      <aside class="panel reveal">
        <h3>How the work is framed</h3>
        <p class="muted">Every offering includes a short diagnosis, a compact framework, and a simple tracking tool. You leave with a plan that fits your calendar.</p>
        <div style="margin-top:14px">
          <strong>Recent focus areas</strong>
          <ul style="margin-top:8px;color:var(--muted)">
            <li>Morning scaffolds for high-velocity schedules</li>
            <li>Midday resets to avoid energy crashes</li>
            <li>Evening closures that prepare the next day</li>
          </ul>
        </div>

        <div style="margin-top:16px">
          <a href="contact.html" class="btn" style="display:inline-block">Ask a question</a>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // Reveal on scroll with reduced-motion check
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches){
        document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible')});
      } else {
        var obs = new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting) en.target.classList.add('visible')})},{threshold:0.12});
        document.querySelectorAll('.reveal').forEach(function(el){obs.observe(el)});
      }
    })();

    // Session Planner logic
    (function(){
      function q(id){return document.getElementById(id)}
      var build = q('buildPlan'), clear = q('clearPlan'), copy = q('copyBtn');
      var result = q('result');

      function getSelectedOptions(sel){var arr=[]; for(var i=0;i<sel.options.length;i++){if(sel.options[i].selected) arr.push(sel.options[i].text);} return arr}

      build.addEventListener('click', function(){
        var goal = q('goal').value.trim();
        var areas = getSelectedOptions(q('focus'));
        var hours = q('hours').value.trim();
        var pace = q('pace').value;
        var notes = q('notes').value.trim();

        if(!goal){result.textContent = 'Please add a clear one-sentence outcome.'; return}

        var lines = [];
        lines.push('{{BUSINESS_NAME}} — Session Plan');
        lines.push('Primary outcome: ' + goal);
        lines.push('Focus areas: ' + (areas.length?areas.join(', '):'General'));
        lines.push('Weekly time commitment: ' + (hours? hours + ' hours':'Not specified'));
        lines.push('Pace: ' + pace);
        if(notes) { lines.push('Notes: ' + notes); }
        lines.push('Recommended first steps:');
        // simple plan builder logic
        if(areas.indexOf('Sleep consistency')>-1 || areas.indexOf('sleep')>-1){
          lines.push('- Morning anchor: wake + 15min light movement; keep wake time within 30 mins daily.');
        }
        if(areas.indexOf('Movement & strength')>-1 || areas.indexOf('movement')>-1){
          lines.push('- Three short sessions of 20 minutes focused movement across the week (bodyweight or mobility).');
        }
        if(areas.indexOf('Stress resets')>-1 || areas.indexOf('stress')>-1){
          lines.push('- Two micro-resets daily: 5 minutes breathing mid-afternoon and 5 minutes of grounding in the evening.');
        }
        if(areas.indexOf('Simple nutrition anchors')>-1 || areas.indexOf('nutrition')>-1){
          lines.push('- Anchor meals: protein at breakfast and a balanced lunch; note one easy swap to reduce energy drag.');
        }
        if(areas.indexOf('Daily rhythm & transitions')>-1 || areas.indexOf('rhythm')>-1){
          lines.push('- Establish a 5-step evening closure that prepares the next morning (list, prep, light movement, hydration, wind-down).');
        }
        if(!areas.length) lines.push('- Pick one micro-habit and test it for three days.');

        lines.push('Tracking: Choose a single metric (sleep time, steps, energy rating) and check it 3x weekly.');
        lines.push('Next review: Schedule 30–45 minute pulse check in 7–14 days.');

        var out = lines.join('\n');
        result.textContent = out;
      });

      clear.addEventListener('click', function(){q('goal').value=''; q('hours').value=''; q('notes').value=''; Array.prototype.forEach.call(q('focus').options,function(o){o.selected=false}); result.textContent='';});

      copy.addEventListener('click', function(){
        var text = result.textContent;
        if(!text) return alert('Nothing to copy — build a plan first');
        navigator.clipboard && navigator.clipboard.writeText(text).then(function(){
          copy.textContent = 'Copied!'; setTimeout(function(){copy.textContent='Copy text'},1200);
        }, function(){ alert('Copy failed — select and copy manually'); });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Courses</title>
  <style>
    :root{--bg:#fcfdff;--accent:#1162a7;--muted:#5b6b7a}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto;background:var(--bg);color:#062033}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:26px auto;padding:20px}
    .intro{background:#fff;border-radius:12px;padding:18px;box-shadow:0 8px 24px rgba(11,34,63,0.04)}
    .list{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:18px}
    .offer{background:linear-gradient(180deg,#fff,#f7fbff);padding:16px;border-radius:10px;border:1px solid rgba(9,56,108,0.04)}
    .meta{font-size:13px;color:var(--muted)}

    /* planner reuse styles */
    .planner{margin-top:18px;border-radius:10px;padding:14px;background:linear-gradient(180deg,#fff,#f8fbff);border:1px solid rgba(11,54,96,0.03)}
    .planner label{display:block;font-size:13px;color:var(--muted);margin-top:10px}
    .planner input[type="text"],.planner textarea, .planner select{width:100%;padding:10px;border-radius:8px;border:1px solid #e6eef8;margin-top:6px}
    .btn{background:var(--accent);color:#fff;padding:10px 12px;border-radius:10px;border:none;font-weight:700;cursor:pointer}
    .small{font-size:13px;color:var(--muted)}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s cubic-bezier(.2,.9,.3,1),transform .6s cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#eaf6ff,#ffffff);display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--accent)">W</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Practical programs for steady results</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I Am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Praise</a>
      <a href="book.html">Plan</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="intro reveal">
      <h1 style="margin:0">Programs built to fit a busy calendar</h1>
      <p class="small">Short cohorts and self-led templates focused on habit architecture, simple tracking, and repeatable rituals. These are not lengthy courses — they are compact, outcome-oriented paths.</p>
    </div>

    <section class="reveal" style="margin-top:18px">
      <h2 style="margin-bottom:8px">Current formats</h2>
      <div class="list">
        <div class="offer">
          <strong>VIP Day Blueprint</strong>
          <div class="meta">A one-day collaboration to design your bespoke week map and first 30-day checklist. Ideal for clients who need a fast, durable reset.</div>
          <div style="margin-top:10px;font-weight:800">Investment: single day engagement</div>
        </div>

        <div class="offer">
          <strong>30-Day Embedding</strong>
          <div class="meta">Four focused check-ins and a living protocol. We iterate weekly until the plan is stable in your routines.</div>
          <div style="margin-top:10px;font-weight:800">Investment: monthly package</div>
        </div>

        <div class="offer">
          <strong>Mini-Cohort: Rhythm Lab</strong>
          <div class="meta">Small group format that teaches one durable routine and group accountability for four weeks. Learn a practice and keep it.</div>
          <div style="margin-top:10px;font-weight:800">Limited seats</div>
        </div>
      </div>
    </section>

    <section class="reveal" style="margin-top:18px">
      <h2>Session Planner</h2>
      <p class="small">Create a concise plan oriented to a program or a VIP Day. Use it to brief me before our session or to bring clarity to your week.</p>

      <div class="planner" id="planner2">
        <label for="p2_goal">Short outcome</label>
        <input id="p2_goal" type="text" placeholder="e.g. settle a 6am start with consistent energy" />

        <label for="p2_scope">Pick a scope</label>
        <select id="p2_scope" multiple size="4">
          <option>Morning protocol</option>
          <option>Midday reset</option>
          <option>Evening closure</option>
          <option>Weekly planning ritual</option>
        </select>

        <label for="p2_horizon">Time horizon</label>
        <select id="p2_horizon"><option>7 days</option><option selected>14 days</option><option>30 days</option></select>

        <label for="p2_notes">Constraints / quick notes</label>
        <textarea id="p2_notes" rows="3" placeholder="e.g. travel, caregiving, meetings"></textarea>

        <div style="margin-top:10px;display:flex;gap:8px">
          <button id="p2_build" class="btn">Create plan</button>
          <button id="p2_clear" class="btn" style="background:#fff;color:var(--accent);border:1px solid rgba(17,84,141,0.08)">Reset</button>
        </div>

        <pre id="p2_result" class="small" style="background:#f2f8ff;padding:10px;border-radius:8px;margin-top:10px;min-height:80px;white-space:pre-wrap"></pre>
        <div style="margin-top:8px"><button id="p2_copy" class="btn">Copy summary</button> <a href="{{PRIMARY_CTA_URL}}" class="btn" style="background:#173f63;margin-left:8px">Book a session</a></div>
      </div>
    </section>

  </main>

  <script>
    // simple reveal respect reduced motion
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches){
        document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible')});
      } else {
        var ob = new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting) e.target.classList.add('visible')})},{threshold:0.12});
        document.querySelectorAll('.reveal').forEach(function(el){ob.observe(el)});
      }
    })();

    // Planner instance 2
    (function(){
      function id(n){return document.getElementById(n)}
      var build = id('p2_build'), clear = id('p2_clear'), copy = id('p2_copy');
      function chosen(sel){var a=[]; for(var i=0;i<sel.options.length;i++) if(sel.options[i].selected) a.push(sel.options[i].text); return a}

      build.addEventListener('click', function(){
        var goal = id('p2_goal').value.trim();
        var scope = chosen(id('p2_scope'));
        var horizon = id('p2_horizon').value;
        var notes = id('p2_notes').value.trim();
        if(!goal){id('p2_result').textContent = 'Please state a clear, single outcome.'; return}
        var out = [];
        out.push('{{BUSINESS_NAME}} — Program Brief');
        out.push('Outcome: ' + goal);
        out.push('Scope: ' + (scope.length?scope.join(', '):'General'));
        out.push('Horizon: ' + horizon);
        if(notes) out.push('Notes: ' + notes);
        out.push('Suggested steps:');
        out.push('- Define 3 micro-actions tied to daily cues.');
        out.push('- Track one core metric 3x a week.');
        out.push('- Mini-review on day 7 and day 14 to adapt.');
        id('p2_result').textContent = out.join('\n');
      });

      clear.addEventListener('click', function(){id('p2_goal').value=''; id('p2_notes').value=''; Array.prototype.forEach.call(id('p2_scope').options,function(o){o.selected=false}); id('p2_result').textContent='';});

      copy.addEventListener('click', function(){var t=id('p2_result').textContent; if(!t) return alert('No summary to copy'); navigator.clipboard.writeText(t).then(function(){copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy summary'},900)}, function(){alert('Copy failed')})});
    })();
  </script>
</body>
</html>"} 
